function dailyEnsure(){if(!speakingBank)return null;const date=dailyDate();if(dailyStudy.date!==date||!Number.isInteger(dailyStudy.part1)||!speakingBank.part1[dailyStudy.part1]||!Number.isInteger(dailyStudy.part2)||!speakingBank.part2[dailyStudy.part2]){dailyStudy={date,part1:Math.floor(Math.random()*speakingBank.part1.length),part2:Math.floor(Math.random()*speakingBank.part2.length),wheelId:null,wheelSource:null,checks:{},draft:''};dailyFlipped.clear();dailySave()}dailyBuildWords();return dailyStudy}
