function dailyWheelColors(){const colors=['#5842ca','#6750d7','#3769bd','#3586b0','#1a897b','#388b74'];return `conic-gradient(${dailyWheelTopics.map((_,i)=>`${colors[i%colors.length]} ${i*12}deg ${(i+1)*12}deg`).join(',')})`}
function renderDailyWheel(){if(!speakingBank){root.innerHTML=heading('Topic barabani','Mavzular yuklanmoqda…')+'<div class="loading"><span class="spinner"></span> Yuklanmoqda…</div>';loadSpeakingBank();return}dailyEnsure();const selected=dailyWheelTopics.find(t=>t.id===dailyStudy.wheelId),index=dailyWheelTopics.findIndex(t=>t.id===selected?.id),rotation=selected?-(index+.5)*12:0;let html=heading('Writing + Listening barabani','30 ta mashq mavzusidan bugun bittasini o‘zingiz aylantirib tanlang.','1 marta / kun');html+='<div class="daily-wheel-layout"><section class="panel daily-wheel-panel"><div class="daily-section-title"><span>03</span><div><h2>Bugungi mavzuni aylantiring</h2><p>Imkon bo‘lsa, baraban bugungi Speaking mavzularidan biriga mos mavzuni tanlaydi.</p></div></div><div class="daily-wheel-wrap"><span class="daily-wheel-pointer" aria-hidden="true"></span><div id="dailyWheelDisc" class="daily-wheel-disc" style="background:'+dailyWheelColors()+';transform:rotate('+rotation+'deg)">'+dailyWheelTopics.map((_,i)=>'<span class="daily-wheel-number" style="--angle:'+(i*12+6)+'deg">'+String(i+1).padStart(2,'0')+'</span>').join('')+'</div><div class="daily-wheel-hub" aria-hidden="true">IELTS</div></div><button type="button" class="primary-btn daily-spin-button" data-action="daily-spin" '+(selected||dailyWheelSpinning?'disabled':'')+'>'+ (selected?'Bugungi mavzu tanlangan':dailyWheelSpinning?'Aylanmoqda…':'Barabanni aylantirish') +'</button><p class="daily-wheel-note">Baraban avtomatik aylanmaydi. Bugun tanlangan mavzu ertagacha saqlanadi.</p></section><section class="panel daily-wheel-side"><h2>Bugungi Speaking mavzulari</h2><div class="daily-wheel-related"><span>PART 1</span><strong>'+esc(speakingBank.part1[dailyStudy.part1].title)+'</strong><span>PART 2</span><strong>'+esc(speakingBank.part2[dailyStudy.part2].title)+'</strong></div>'+(selected?'<div class="daily-result" role="status"><small>'+ (dailyStudy.wheelSource==='speaking'?'SPEAKING BILAN BOG‘LIQ MAVZU':'BUGUNGI MAVZU')+'</small><h3>'+esc(selected.label)+'</h3><p>'+esc(selected.uz)+'</p></div>':'<div class="daily-result daily-result-empty" role="status"><h3>Natija hali yo‘q</h3><p>Bugungi Writing va Listening mavzusini tanlash uchun barabanni bosing.</p></div>')+'</section></div>';
 if(selected){const checks=dailyStudy.checks||{};html+=`<section class="daily-section daily-wheel-tasks"><div class="daily-section-title"><span>04</span><div><h2>Bugungi o‘qish, yozish va eshitish</h2><p>Topshiriqlarni bajarganingizda belgilang. Essay matni shu kun uchun saqlanadi.</p></div></div><div class="daily-task-grid"><label class="daily-task"><input type="checkbox" data-daily-task="article" ${checks.article?'checked':''}><span><strong>Article o‘qish</strong><small>Mavzu: ${esc(selected.read)}</small><a href="https://www.google.com/search?q=${encodeURIComponent(selected.read+" article IELTS")}" target="_blank" rel="noopener noreferrer">Maqola qidirish ↗</a></span></label><label class="daily-task"><input type="checkbox" data-daily-task="essay" ${checks.essay?'checked':''}><span><strong>Essay yozish</strong><small>Quyidagi savolga fikr bildiring.</small></span></label><label class="daily-task"><input type="checkbox" data-daily-task="podcast" ${checks.podcast?'checked':''}><span><strong>Podcast eshitish</strong><small>Mavzu: ${esc(selected.listen)}</small><a href="https://www.youtube.com/results?search_query=${encodeURIComponent(selected.listen+" podcast English")}" target="_blank" rel="noopener noreferrer">Podkast qidirish ↗</a></span></label></div><div class="daily-essay"><h3>Writing Task 2 · mashq savoli</h3><p lang="en">${esc(selected.essay)}</p><label for="dailyEssayDraft">Essay qoralamangiz</label><textarea id="dailyEssayDraft" rows="9" placeholder="Write your introduction, main points and conclusion here...">${esc(dailyStudy.draft||'')}</textarea><div class="daily-essay-footer"><span id="dailyEssayCount">${(dailyStudy.draft||'').trim().split(/\s+/).filter(Boolean).length} so‘z</span><button type="button" class="secondary-btn" data-action="daily-save-essay">Qoralamani saqlash</button></div></div></section>`}
 html+='<section class="daily-section daily-topic-catalog"><div class="daily-section-title"><span>30</span><div><h2>Barabandagi barcha mavzular</h2><p>Bu o‘quv mashqi uchun mavzular; ular imtihon chastotasi reytingi emas.</p></div></div><ol>'+dailyWheelTopics.map((t,i)=>'<li class="'+(t.id===dailyStudy.wheelId?'is-selected':'')+'"><b>'+String(i+1).padStart(2,'0')+'</b><span>'+esc(t.label)+'</span><small>'+esc(t.uz)+'</small></li>').join('')+'</ol></section>';root.innerHTML=html}
function dailySpin(){if(!speakingBank||!dailyEnsure()||dailyStudy.wheelId||dailyWheelSpinning)return;const matched=[dailyTopicId(speakingBank.part1[dailyStudy.part1].title),dailyTopicId(speakingBank.part2[dailyStudy.part2].title)].filter(Boolean);const ids=[...new Set(matched)];const chosen=ids.length?ids[Math.floor(Math.random()*ids.length)]:dailyWheelTopics[Math.floor(Math.random()*dailyWheelTopics.length)].id;dailyStudy.wheelId=chosen;dailyStudy.wheelSource=ids.length?'speaking':'random';dailySave();const index=dailyWheelTopics.findIndex(t=>t.id===chosen),wheel=$('#dailyWheelDisc'),button=$('.daily-spin-button');dailyWheelSpinning=true;if(button){button.disabled=true;button.textContent='Aylanmoqda…'}if(wheel){wheel.style.transition='transform 4s cubic-bezier(.14,.8,.16,1)';requestAnimationFrame(()=>{wheel.style.transform=`rotate(${1800-(index+.5)*12}deg)`})}clearTimeout(dailyWheelTimer);dailyWheelTimer=setTimeout(()=>{dailyWheelSpinning=false;if(state.view==='wheel')renderDailyWheel()},4200)}
function dailyHandleAction(action,button){if(action==='daily-spin'){dailySpin();return true}if(action==='daily-card-flip'){const key=button.dataset.key;if(dailyFlipped.has(key))dailyFlipped.delete(key);else dailyFlipped.add(key);const front=button.querySelector('strong'),hint=button.querySelector('span'),label=button.querySelector('small');const card=dailyWordsById.get(key)||(()=>{const [qid,n]=key.split(':');const q=[...speakingBank.part1[dailyStudy.part1].questions,...speakingBank.part2[dailyStudy.part2].questions].find(x=>x.id===qid);return q?.cards[Number(n)]})();if(card){const back=dailyFlipped.has(key);button.classList.toggle('is-flipped',back);button.setAttribute('aria-pressed',String(back));front.textContent=back?card.u:card.w;hint.textContent=back?card.e:'Tarjimani ko‘rish ↗';label.textContent=back?'O‘ZBEKCHA TARJIMA':'INGLIZCHA IBORA'}return true}if(action==='daily-card-speak'){pronounce(button.dataset.phrase);return true}if(action==='daily-start-game'){dailyEnsure();const mode=button.dataset.mode;if(!games.some(g=>g[0]===mode))return true;startGame(mode,dailyWords,{section:`daily:${dailyStudy.date}`,packIndex:0,label:`Bugungi iboralar · ${games.find(g=>g[0]===mode)[1]}`,origin:'daily'});return true}if(action==='daily-save-essay'){dailySave();toast('Bugungi essay qoralamasi saqlandi.');return true}return false}

