function lbThumbFallback(title='',channel=''){const t=String(title||'Listening').replace(/[&<>"']/g,m=>({ '&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[m]||m));const c=String(channel||'VIVID IELTS').replace(/[&<>"']/g,m=>({ '&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[m]||m));const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1280 720"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#2a1c8c"/><stop offset="0.55" stop-color="#5a43d5"/><stop offset="1" stop-color="#e56b47"/></linearGradient></defs><rect width="1280" height="720" fill="url(#g)"/><circle cx="1080" cy="120" r="180" fill="rgba(255,255,255,0.12)"/><circle cx="1180" cy="20" r="240" fill="rgba(255,255,255,0.08)"/><text x="76" y="120" font-family="Arial, Helvetica, sans-serif" font-size="34" font-weight="700" fill="#F5F0FF">${c}</text><text x="76" y="220" font-family="Arial, Helvetica, sans-serif" font-size="72" font-weight="800" fill="white">${t}</text><rect x="76" y="560" rx="28" ry="28" width="250" height="70" fill="rgba(20,24,38,0.74)"/><text x="106" y="606" font-family="Arial, Helvetica, sans-serif" font-size="28" font-weight="700" fill="white">🎧 AUDIO ONLY</text></svg>`;return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`}
