document.addEventListener('change',e=>{if(lbHandleChange(e.target))return;if(rbHandleChange(e.target))return;if(e.target.id==='maxSpeakingTopic'){maxSpeakingTopic=Number(e.target.value);maxSpeakingPage=0;renderMaxSpeaking();return}if(e.target.id==='maxSpeakingKind'){maxSpeakingKind=e.target.value;maxSpeakingPage=0;renderMaxSpeaking();return}if(e.target.dataset.dailyTask&&['article','essay','podcast'].includes(e.target.dataset.dailyTask)){dailyEnsure();dailyStudy.checks[e.target.dataset.dailyTask]=e.target.checked;dailySave();return}if(e.target.id==='grammarSource'||e.target.id==='grammarGameScope'){state.grammarSource=e.target.value;state.grammarPage=0;state.grammarFlipped=false;(state.view==='grammar'?renderGrammarLibrary():renderGrammarGames())}if(e.target.id==='gameScope'){state.scope=e.target.value;renderGames()}if(e.target.id==='backupInput'){importBackup(e.target.files?.[0])}});
